<template>
  <Teleport to="body">
    <Transition name="music-panel" @after-leave="releaseAnchor">
      <div v-if="open" class="music-panel-anchor" :class="{ 'opens-above': above, 'keyboard-open': keyboardOpen }" :style="position" @pointerenter="hold" @pointerleave="scheduleClose" @focusout="onFocusOut">
        <section id="site-music-panel" ref="panel" class="music-panel" role="dialog" aria-label="Music controls" @pointerdown="keyboardOpen = false" @keydown.esc.stop.prevent="close(true)">
          <header class="music-track">
            <div class="music-art" :class="{ 'is-playing': state.playing }" aria-hidden="true">
              <img v-if="state.track.cover && !coverFailed" :src="state.track.cover" alt="" width="52" height="52" @error="coverFailed = true" />
              <div v-else class="music-record"><span></span></div>
            </div>
            <div class="music-track-copy" aria-live="polite" aria-atomic="true">
              <h2>{{ state.track.title }}</h2>
              <div class="music-artist-row">
                <p>{{ state.track.artist || 'Background music' }}</p>
                <span class="music-wave" :class="{ 'is-playing': state.playing && !state.loading }" aria-hidden="true">
                  <span v-for="bar in 5" :key="bar"></span>
                </span>
              </div>
            </div>
          </header>

          <div class="music-transport">
            <button ref="firstControl" type="button" aria-label="Previous track" @click="command('previous')">
              <svg viewBox="0 0 24 24" aria-hidden="true"><path class="solid" d="M6 5h2v14H6zm13 1v12L9 12z" /></svg>
            </button>
            <button class="music-play" type="button" :aria-label="state.playing ? 'Pause music' : 'Play music'" :aria-busy="state.loading" @click="command('toggle')">
              <svg viewBox="0 0 24 24" aria-hidden="true"><path class="solid" :d="state.playing ? 'M7 5h3v14H7zm7 0h3v14h-3z' : 'm8 5 11 7-11 7z'" /></svg>
            </button>
            <button type="button" aria-label="Next track" @click="command('next')">
              <svg viewBox="0 0 24 24" aria-hidden="true"><path class="solid" d="M16 5h2v14h-2zM5 6v12l10-6z" /></svg>
            </button>
          </div>

          <div class="music-progress">
            <input type="range" min="0" :max="state.duration || 1" step="1" :value="scrubTime ?? state.time" :style="{ '--range-fill': progress + '%' }" aria-label="Track position" :aria-valuetext="`${clock(scrubTime ?? state.time)} of ${clock(state.duration)}`" @input="scrubTime = Number($event.target.value)" @change="seek" @pointerdown="dragging = true" @lostpointercapture="finishDrag" @pointercancel="cancelSeek" />
            <div class="music-times"><span>{{ clock(scrubTime ?? state.time) }}</span><span>{{ clock(state.duration) }}</span></div>
          </div>

          <div class="music-volume">
            <button type="button" :aria-label="state.volume === 0 ? 'Unmute music' : 'Mute music'" @click="toggleMute">
              <svg viewBox="0 0 24 24" aria-hidden="true"><path d="m11 5-5 4H3v6h3l5 4z" /><path v-if="state.volume > 0" d="M15 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14" /><path v-else d="m16 9 5 6m0-6-5 6" /></svg>
            </button>
            <input type="range" min="0" max="100" step="1" :value="Math.round(state.volume * 100)" :style="{ '--range-fill': state.volume * 100 + '%' }" aria-label="Music volume" :aria-valuetext="`${Math.round(state.volume * 100)} percent`" @input="changeVolume" @pointerdown="dragging = true" @lostpointercapture="finishDrag" />
          </div>
          <p v-if="state.error" class="music-error" role="status">{{ state.error }}</p>
        </section>
      </div>
    </Transition>
  </Teleport>
</template>

<script>
export default {
  name: 'MusicControls',
  data: () => ({
    open: false, above: false, keyboardOpen: false, position: {}, dragging: false,
    scrubTime: null, lastVolume: 1, coverFailed: false,
    state: { track: { title: 'Music', artist: '', cover: '' }, time: 0, duration: 0, playing: false, loading: false, volume: 1, error: '' },
  }),
  computed: {
    progress() { return Math.min(100, (this.scrubTime ?? this.state.time) / (this.state.duration || 1) * 100); },
  },
  watch: {
    '$route.fullPath'() { this.close(); },
  },
  mounted() {
    this._triggers = Array.from(document.querySelectorAll('[data-music-control]'));
    this._onState = event => {
      if (event.detail.track.src !== this.state.track.src) { this.coverFailed = false; this.scrubTime = null; }
      this.state = event.detail;
      if (event.detail.volume > 0) this.lastVolume = event.detail.volume;
    };
    this._onEnter = event => {
      if (event.pointerType !== 'mouse' || !this.canOpen()) return;
      this.hold();
      const anchor = event.currentTarget;
      this._openTimer = setTimeout(() => this.show(anchor), 90);
    };
    this._onFocus = event => {
      if (this._returningFocus) return;
      if (this.canOpen() && event.currentTarget.matches(':focus-visible')) this.show(event.currentTarget, true);
    };
    this._onKey = event => {
      if (!this.canOpen()) return;
      if (event.key === 'ArrowDown' || (this.open && event.key === 'Tab' && !event.shiftKey)) {
        event.preventDefault();
        this.show(event.currentTarget, true);
        this.$nextTick(() => this.$refs.firstControl?.focus());
      } else if (event.key === 'Escape') this.close();
    };
    this._onOutside = event => {
      if (this.open && !this.$refs.panel?.contains(event.target) && !this._anchor?.contains(event.target)) this.close();
    };
    this._onResize = () => { this.updateAvailability(); if (this.open) this.place(); };
    this._triggers.forEach(trigger => {
      trigger.addEventListener('pointerenter', this._onEnter);
      trigger.addEventListener('pointerleave', this.scheduleClose);
      trigger.addEventListener('focus', this._onFocus);
      trigger.addEventListener('blur', this.onFocusOut);
      trigger.addEventListener('keydown', this._onKey);
    });
    window.addEventListener('site-music-state', this._onState);
    window.addEventListener('resize', this._onResize);
    window.addEventListener('scroll', this.place, { passive: true });
    document.addEventListener('pointerdown', this._onOutside, true);
    this.updateAvailability();
    this.command('request');
  },
  beforeUnmount() {
    this.close();
    this.releaseAnchor();
    this._triggers.forEach(trigger => {
      trigger.removeEventListener('pointerenter', this._onEnter);
      trigger.removeEventListener('pointerleave', this.scheduleClose);
      trigger.removeEventListener('focus', this._onFocus);
      trigger.removeEventListener('blur', this.onFocusOut);
      trigger.removeEventListener('keydown', this._onKey);
    });
    window.removeEventListener('site-music-state', this._onState);
    window.removeEventListener('resize', this._onResize);
    window.removeEventListener('scroll', this.place);
    document.removeEventListener('pointerdown', this._onOutside, true);
  },
  methods: {
    canOpen() { return window.matchMedia('(min-width: 761px) and (hover: hover) and (pointer: fine)').matches; },
    updateAvailability() {
      const enabled = this.canOpen();
      this._triggers.forEach(trigger => {
        if (enabled) trigger.setAttribute('aria-haspopup', 'dialog');
        else { trigger.removeAttribute('aria-haspopup'); trigger.removeAttribute('aria-expanded'); }
      });
      if (!enabled) this.close();
    },
    show(anchor, keyboard = false) {
      if (!anchor || !this.canOpen()) return;
      this.hold();
      if (this._anchor && this._anchor !== anchor) {
        this._anchor.removeAttribute('aria-controls');
        this._anchor.setAttribute('aria-expanded', 'false');
        this._anchor.classList.remove('music-controls-open');
      }
      this._anchor = anchor;
      anchor.setAttribute('aria-expanded', 'true');
      anchor.setAttribute('aria-controls', 'site-music-panel');
      anchor.classList.add('music-controls-open');
      this.keyboardOpen = keyboard;
      this.open = true;
      this.command('request');
      this.place();
      this.$nextTick(this.place);
    },
    place() {
      if (!this.open || !this._anchor) return;
      const box = this._anchor.getBoundingClientRect();
      if (!box.width || box.bottom < 0 || box.top > innerHeight) { this.close(); return; }
      const height = (this.$refs.panel?.offsetHeight || 238) + 14;
      const left = Math.max(12, Math.min(innerWidth - 308, box.right - 296));
      this.above = box.bottom + height > innerHeight - 12 && box.top > height;
      this.position = { left: `${left}px`, top: `${this.above ? box.top - height : box.bottom}px`, '--music-tail': `${Math.max(20, Math.min(276, box.left + box.width / 2 - left))}px` };
    },
    hold() { clearTimeout(this._closeTimer); clearTimeout(this._openTimer); },
    scheduleClose() {
      this.hold();
      this._closeTimer = setTimeout(() => {
        if (this.$refs.panel?.matches(':hover') || this._anchor?.matches(':hover')) return;
        if (!this.dragging && !(this.keyboardOpen && this.$refs.panel?.contains(document.activeElement))) this.close();
      }, 180);
    },
    onFocusOut() {
      this.$nextTick(() => {
        if (!this.$refs.panel?.contains(document.activeElement) && document.activeElement !== this._anchor) this.scheduleClose();
      });
    },
    close(returnFocus = false) {
      this.hold();
      this.open = false;
      this.dragging = false;
      this.scrubTime = null;
      this._anchor?.setAttribute('aria-expanded', 'false');
      this._anchor?.classList.remove('music-controls-open');
      if (returnFocus && this._anchor?.isConnected) {
        this._returningFocus = true;
        this._anchor.focus({ preventScroll: true });
        this._returningFocus = false;
      }
    },
    releaseAnchor() { if (!this.open) { this._anchor?.removeAttribute('aria-controls'); this._anchor = null; } },
    command(action, values = {}) {
      window.dispatchEvent(new CustomEvent(action === 'request' ? 'site-music-request' : 'site-music-command', { detail: { action, ...values } }));
    },
    clock(seconds) { const time = Math.max(0, Math.floor(seconds || 0)); return `${Math.floor(time / 60)}:${String(time % 60).padStart(2, '0')}`; },
    seek(event) { this.command('seek', { time: Number(event.target.value) }); this.scrubTime = null; this.dragging = false; },
    cancelSeek() { this.scrubTime = null; this.finishDrag(); },
    finishDrag() { this.dragging = false; if (!this.$refs.panel?.matches(':hover')) this.scheduleClose(); },
    changeVolume(event) { this.command('volume', { volume: Number(event.target.value) / 100 }); },
    toggleMute() { this.command('volume', { volume: this.state.volume === 0 ? this.lastVolume : 0 }); },
  },
};
</script>

